const items = $input.all();
const item0 = items[0].json;

const totalVenta = items.reduce((sum, i) => sum + parseFloat(i.json.subtotal), 0);

const productosLineas = items.map(i =>
    ` ${i.json.nombre_producto} (ID: ${i.json.producto_id})\n   Cant: ${i.json.cantidad} | Precio: Q${i.json.precio_unitario} | Subtotal: Q${parseFloat(i.json.subtotal).toFixed(2)}`
).join('\n');

const filasHTML = items.map(i => `
    <tr>
        <td>${i.json.producto_id}</td>
        <td>${i.json.nombre_producto}</td>
        <td>${i.json.cantidad}</td>
        <td>Q${i.json.precio_unitario}</td>
        <td>Q${parseFloat(i.json.subtotal).toFixed(2)}</td>
    </tr>
`).join('');

const telegramMsg = `🛒 Nueva venta registrada

Venta ID: #${item0.venta_id}
Cliente ID: ${item0.cliente_id}
Cliente: ${item0.nombre_cliente}
Total: Q${totalVenta.toFixed(2)}

Productos:
${productosLineas}`;

return [{
    json: {
        venta_id: item0.venta_id,
        cliente_id: item0.cliente_id,
        nombre_cliente: item0.nombre_cliente,
        total: totalVenta.toFixed(2),
        filas_html: filasHTML,
        telegram: telegramMsg
    }
}];
